    "noDeadline": true,
    "publishDate": "2026-10-14",
    "officialLink": "https://pid.gov.pk/site/press_detail/34272",
    "applyLink": "https://pid.gov.pk/site/press_detail/34272",
    "isVerified": true,
    "featured": true,
    "logoInitial": "PID",
    "featuredImage": "/images/wheat-imports-karachi-october-2026.webp",
