    "lastDate": "2026-10-12",
    "noDeadline": false,
    "publishDate": "2026-10-05",
    "officialLink": "https://cbdpunjab.gov.pk/ycp2026",
    "applyLink": "https://careers.accelerec.com/career/pcbdda",
    "isVerified": true,
